    const o = order(rows, t);
    expect([o[0], [o[1], o[2]].sort(), o[3], o[4], o[5]]).toEqual(["T", ["P", "Q"], "R", "S", "U"]);
    const pq = [t.P!, t.Q!].sort();
    const draws = (await lotsDraws(s.stageId)).filter((d) => JSON.stringify([...d.members].sort()) === JSON.stringify(pq));
    expect(draws, "P and Q went to a stored drawing of lots, once").toHaveLength(1);
    expect([o[1], o[2]].map((k) => t[k!]), "ranked by the stored draw").toEqual(draws[0]!.drawn_order);
    expect([rowOf(rows, t.P!).tieBreak?.key, rowOf(rows, t.Q!).tieBreak?.key], "lots, not direct, split them").toEqual(["lots", "lots"]);
